  // (프레임 열거 자체가 불가능한 환경이거나 프레임 스크립트 실행이 실패한 경우. 평소에는 비어 있다.)
  crossOriginFrames?: string[]
  // 최상위 문서 JS 가 "안을 못 본" 프레임 목록(내부용) — 위 두 목록과 대조해 무엇이 진짜 미관찰인지 가린다.
  frameStubs?: Array<{ src: string; label: string }>
  // 관찰 세대(epoch) — 이 관찰에서 나온 ref 번호들은 이 토큰과 짝일 때만 유효하다는 표. 실행 함수에
  // epoch 를 함께 넘기면, 그 사이 재관찰(다른 탭에 갔다 오거나 SPA 재렌더 후 다시 observePage)이 있었는지
  // pick() 이 검증한다 — 옛 번호로 "지금 화면의 다른 요소"를 집는 사고를 막는다(과제1). 탭 id 를 섞어
  // 탭이 달라도 절대 같은 토큰이 나오지 않는다(같은 이유로 다른 탭의 ref 는 애초에 먹히지 않는다).
  epoch: string
}

export interface AgentAction {
  thought?: string
  action: 'click' | 'type' | 'navigate' | 'scroll' | 'read' | 'wait' | 'done' | 'ask' | 'open_tab' | 'switch_tab' | 'close_tab' | 'remember' | 'upload_file' | 'click_at' | 'extract'
    | 'wait_for' | 'key' | 'hover' | 'drag' | 'download' | 'run_js' | 'autofill' | 'note' | 'report' | 'expect'
    | 'select' | 'request_scope'
  ref?: number
  text?: string
  url?: string
  urlContains?: string   // expect: 현재 URL 에 이 문자열이 포함돼야 통과
  urlChanged?: boolean   // expect: 동작 전과 URL 이 달라졌으면 통과(문구를 모를 때)
  changed?: boolean      // expect: 화면(본문·요소)이 유의미하게 바뀌었으면 통과(문구를 모를 때) — 바뀐 내용이 done 에 요약된다
  index?: number         // switch_tab 대상 탭 번호
  direction?: 'up' | 'down'
  message?: string
  submit?: boolean       // type 후 Enter 로 제출
  name?: string          // upload_file: 지정 폴더 안 파일 이름
  xPct?: number          // click_at / drag: 화면 가로의 0~100 (%)
  yPct?: number          // click_at / drag: 화면 세로의 0~100 (%)
  rowSelector?: string   // extract: 반복 항목 CSS 선택자
  fields?: Record<string, string>            // extract: { 열이름: 선택자(@attr 지원) }
  rows?: Array<Record<string, unknown>>      // extract: 직접 제공한 데이터 행들
  selector?: string      // wait_for: 나타나길 기다릴 CSS 선택자
  timeout?: number       // wait_for: 최대 대기(ms)
  key?: string           // key: 키/조합 (예 "Enter","Tab","Control+a")
  code?: string          // run_js: 실행할 자바스크립트
  toRef?: number         // drag: 목적지 요소 번호
  toXPct?: number        // drag: 목적지 가로 %
  toYPct?: number        // drag: 목적지 세로 %
  title?: string         // report: 보고서 제목
  markdown?: string      // report: 개요·핵심 결론(본문은 누적 note 로 조립)
  host?: string          // request_scope: 허용 목록에 추가를 요청할 호스트(사용자 승인 필요)
}

// ===== ref 레지스트리 (DOM 을 건드리지 않는 요소 참조) =====
// 예전에는 관찰할 때마다 요소에 data-bb-agent-ref 속성을 달았다. 그러나 인스타·페북 등은 MutationObserver 로
// 자기 DOM 변화를 상시 감시하므로, 매 단계 수십 개 속성이 붙었다 지워지는 패턴은 그 자체로 자동화 지문이었다
// (`document.querySelector('[data-bb-agent-ref]')` 한 줄이면 탐지). 이제 DOM 을 전혀 수정하지 않고,
// 페이지 JS 컨텍스트의 배열에 요소 참조를 담아 번호로 집는다 — 속성 변경 0, MutationObserver 에 아무것도 안 잡힌다.
// 전역 키는 실행마다 무작위라 페이지가 이름을 하드코딩해 탐지할 수도 없다.
const REF_KEY = '__' + Math.random().toString(36).slice(2, 10)

// 집기 — 번호로 요소를 꺼내되, 그 사이 화면이 바뀌었는지 검증한다.
// 가상 스크롤(피드)은 DOM 노드를 재활용하므로, 관찰 때 본 이름과 지금 이름이 다르면 다른 항목이 된 것이다.
// 그대로 클릭하면 엉뚱한 게시물에 좋아요·신고를 누르게 되므로 null 을 돌려 재관찰을 유도한다.
// 두 번째 인자 epoch(과제1) — 넘기면 지금 레지스트리의 세대와 일치하는지, 요소가 속한 문서(프레임)가
// 관찰 당시와 같은 페이지인지까지 검증한다. 실패 사유는 pick.reason 에 남겨(함수 객체 프로퍼티 — 같은
// executeJavaScript 안에서 pick() 직후 동기적으로 읽으면 항상 그 호출의 결과다) 호출부가 사람이 읽을
// 메시지를 만들 수 있게 한다. epoch 를 안 넘기면(하위호환) 세대·프레임 검사를 생략하고 예전과 동일하게 동작한다.
const PICK_FN = `function pick(r,epoch){pick.reason='';var A=window['${REF_KEY}'];if(!A){pick.reason='stale';return null;}`
  // 관찰 세대(epoch) 불일치 — 탭을 전환했다 돌아오거나 SPA 재렌더 후 다시 observePage 를 부르면 레지스트리가
  // 통째로 새로 만들어지며 __epoch 도 바뀐다(observePage 참고). 옛 번호를 그대로 쓰면 지금 화면에서 그 자리에
  // 나타난 "다른" 요소를 집게 되므로, 넘어온 epoch 가 지금 것과 다르면 즉시 거부한다.
  + `if(epoch!=null&&A.__epoch!==epoch){pick.reason='epoch';return null;}`
  + `var it=A[r];if(!it||!it.e){pick.reason='stale';return null;}var el=it.e;`
  // 프레임 검사 — 요소가 속한 문서(top 또는 same-origin iframe)의 현재 URL 이 관찰 당시 기록한 것과
  // 다르면 거부한다. iframe 이 새 페이지로 넘어간 뒤 같은 슬롯에 생긴 다른 요소(예: 결제 iframe 이 다음
  // 단계로 넘어간 뒤 남은 참조로 그 화면의 버튼을 누르는 사고)를 막는다. cross-origin 프레임은 관찰
  // 단계에서부터 수집되지 않으므로(같은 파일의 collect() 주석 참고) 여기서 SecurityError 가 날 일은
  // 없지만, 어떤 이유로든 접근이 막히면 통과시킨다(과잉 차단보다 재관찰 유도가 먼저인 다른 검사들과 달리,
  // 이 값을 못 읽는 것 자체는 화면이 바뀌었다는 증거가 아니다). epoch 검사와 마찬가지로 epoch 를 넘긴
  // 호출자에게만 적용한다 — 아직 epoch 를 안 넘기는 호출자(agent.ts 배선 전)의 기존 동작을 그대로 보존.
  + `try{if(epoch!=null&&it.f){var fw=(el.ownerDocument&&el.ownerDocument.defaultView)||null;var curF=fw?((fw.location&&fw.location.href)||''):'';if(curF&&curF!==it.f){pick.reason='frame';return null;}}}catch(e){}`
  // React 재렌더로 관찰 때 요소가 DOM 에서 떨어지면(인스타 사이드바 "새로운 게시물" — 실사이트 2회 재현) 같은 이름의 요소를 다시 찾는다.
  + `try{if(!el.isConnected){var Q='a[href],button,input,select,textarea,[role=button],[role=link],[role=tab],[role=menuitem],[role=option],[contenteditable=true],[onclick],[tabindex]';var cand=document.querySelectorAll(Q);var found=null;for(var qi=0;qi<cand.length&&!found;qi++){var ce=cand[qi];var cn='';try{cn=(ce.getAttribute('aria-label')||ce.getAttribute('placeholder')||ce.innerText||ce.textContent||'').replace(/\\s+/g,' ').trim();}catch(e){}if(cn&&it.n&&(cn===it.n||cn.indexOf(it.n)===0)){var cr=ce.getBoundingClientRect();if(cr.width>0&&cr.height>0)found=ce;}}if(!found){pick.reason='stale';return null;}el=found;it.e=found;}}catch(e){}`
  // 이름 계산은 관찰(nameOf)과 **같은 순서**여야 한다 — 다르면 라벨로 이름 붙은 입력칸("설명")·라디오("공개")가
  // value 와 비교돼 "다른 요소" 로 거부된다(2026-09-13, SNS 하네스 S3·S4).

content.content:
1	import { webFrameMain, type WebContents, type WebFrameMain } from 'electron'
2	
3	// ===== 교차 출처(cross-origin) 프레임 제어 =====
4	//
5	// 왜 필요한가: 관찰·조작 스크립트는 `wc.executeJavaScript` 로 **최상위 문서에서만** 돌았다. 같은 출처
6	// iframe 은 그 스크립트가 `contentDocument` 로 재귀해 들어가지만, 다른 출처 iframe 은 같은 출처 정책(SOP)
7	// 때문에 페이지 JS 로는 절대 들여다볼 수 없다. 그래서 로그인·결제·업로드 UI 가 iframe 인 사이트에서
8	// 에이전트는 "여기 프레임이 있는데 못 본다" 로 멈췄다.
9	//
10	// 그러나 **브라우저 메인 프로세스에는 그 제한이 없다.** Electron 의 WebFrameMain
11	// (https://www.electronjs.org/docs/latest/api/web-frame-main) 은 프레임 트리의 모든 프레임을 주고,
12	// `frame.executeJavaScript` 는 그 프레임의 문서 컨텍스트에서 직접 실행된다. SOP 는 "페이지 안의 JS 가
13	// 다른 출처 문서를 읽는 것" 을 막는 규칙이지, 브라우저 자신이 자기 프레임에 접근하는 것을 막는 규칙이 아니다.
14	// (웹 페이지 DOM 의 SOP 제한과 브라우저 메인 권한을 혼동하면 "구조상 불가" 라는 잘못된 결론이 나온다.)
15	//
16	// 보안·정책은 그대로 유지한다:
17	//   · webPreferences(sandbox·contextIsolation·webSecurity)는 건드리지 않는다 — 여기서 하는 일은
18	//     렌더러 권한 완화가 아니라, 메인 프로세스가 자기 프레임에 스크립트를 실행하는 것뿐이다.
19	//   · 허용 사이트(allowedHosts) 정책을 **자식 프레임에도 그대로** 적용한다. 허용 목록 밖 프레임은
20	//     스크립트를 아예 실행하지 않는다 — 그 안의 텍스트·요소가 모델 프롬프트로 한 글자도 가지 않는다.
21	//     (호스트 이름만 "여기 못 보는 프레임이 있다" 로 보고해, 사용자가 명시 승인으로 범위를 넓힐 수 있게 한다.)
22	
23	const MAX_FRAME_DEPTH = 5        // 광고 프레임이 겹겹이 쌓인 페이지에서 무한 순회 방지
24	const MAX_OBSERVE_FRAMES = 6     // 한 관찰에서 스크립트를 돌릴 교차출처 프레임 상한(프롬프트 폭발 방지)
25	const MAX_BLOCKED_REPORT = 6
26	
27	export interface FrameRoot {
28	  id: string            // '<processId>:<routingId>' — 실행 시점에 다시 찾기 위한 키
29	  frame: WebFrameMain
30	  url: string
31	  host: string
32	  depth: number
33	}
34	
35	export interface BlockedFrame {
36	  host: string
37	  reason: 'not-allowed'
38	}
39	
40	export function frameKey(frame: WebFrameMain): string {
41	  return `${frame.processId}:${frame.routingId}`
42	}
43	
44	function originOf(u: string): string {
45	  try { return new URL(u).origin } catch { return '' }
46	}
47	
48	function safeUrl(frame: WebFrameMain): string {
49	  try { return frame.url } catch { return '' }
50	}
51	
52	export function hostOf(u: string): string {
53	  try { return new URL(u).hostname.toLowerCase() } catch { return '' }
54	}
55	
56	// 허용 호스트 검사 — 사용자가 "이 사이트들에서만" 이라고 정한 범위를 코드로 강제한다.
57	// 프롬프트 지시만으로는 모델이 다른 사이트로 새는 것을 막을 수 없다. 최상위 이동(navigate/open_tab)과
58	// **자식 프레임 관찰** 이 같은 함수를 쓴다 — 규칙이 두 벌이면 한쪽만 조여지는 구멍이 생긴다.
59	export function hostAllowed(url: string, allowed: string[] | undefined): boolean {
60	  if (!allowed || allowed.length === 0) return true
61	  const host = hostOf(url)
62	  if (!host) return false
63	  return allowed.some((a) => {
64	    const want = String(a ?? '').trim().toLowerCase().replace(/^\*\./, '')
65	    if (!want) return false
66	    return host === want || host.endsWith('.' + want)
67	  })
68	}
69	
70	// 스크립트를 따로 돌려야 하는 프레임(= 부모 문서의 JS 로는 닿을 수 없는 프레임)만 고른다.
71	// 부모와 같은 출처인 프레임은 부모 관찰 스크립트가 이미 contentDocument 로 재귀해 들어갔으므로 제외한다.
72	export function listObservationFrames(
73	  wc: WebContents,
74	  allowedHosts: string[] | undefined,
75	): { roots: FrameRoot[]; blocked: BlockedFrame[] } {
76	  const roots: FrameRoot[] = []
77	  const blocked: BlockedFrame[] = []
78	  let main: WebFrameMain | null = null
79	  try { main = wc.mainFrame } catch { return { roots, blocked } }
80	  if (!main) return { roots, blocked }
81	
82	  const seenBlockedHosts = new Set<string>()
83	  const visit = (parent: WebFrameMain, depth: number): void => {
84	    if (depth > MAX_FRAME_DEPTH || roots.length >= MAX_OBSERVE_FRAMES) return
85	    let kids: WebFrameMain[] = []
86	    try { kids = parent.frames } catch { return }
87	    const parentOrigin = originOf(safeUrl(parent))
88	    for (const k of kids) {
89	      if (roots.length >= MAX_OBSERVE_FRAMES) return
90	      const url = safeUrl(k)
91	      const org = originOf(url)
92	      // 부모와 같은 출처 → 부모 스크립트가 이미 본다. 그 아래로만 계속 내려간다.
93	      if (org && parentOrigin && org === parentOrigin) { visit(k, depth + 1); continue }
94	      // about:blank / about:srcdoc / data: 등은 부모 출처를 상속해 부모 JS 로 닿는다(또는 볼 내용이 없다).
95	      if (!/^https?:/i.test(url)) continue
96	      if (!hostAllowed(url, allowedHosts)) {
97	        // 허용 목록 밖 — 스크립트를 실행하지 않는다. 안의 텍스트는 모델로 가지 않고, 호스트만 보고한다.
98	        // 그 아래 자손도 보지 않는다(부모를 못 보는데 자식만 읽는 것은 정책 우회다).
99	        const h = hostOf(url)
100	        if (h && !seenBlockedHosts.has(h) && blocked.length < MAX_BLOCKED_REPORT) {
101	          seenBlockedHosts.add(h)
102	          blocked.push({ host: h, reason: 'not-allowed' })
103	        }
104	        continue
105	      }
106	      roots.push({ id: frameKey(k), frame: k, url, host: hostOf(url), depth })
107	      visit(k, depth + 1)
108	    }
109	  }
110	  visit(main, 1)
111	  return { roots, blocked }
112	}
113	
114	// id 로 프레임을 되찾는다. 프레임이 사라졌거나(detach) 다른 문서로 바뀌었으면 null 을 준다 —
115	// 실행 시점에 반드시 다시 확인해야 한다. 관찰 때의 핸들을 그대로 믿으면, 그 사이 프레임이 재로드된
116	// 화면에서 "옛 프레임의 번호" 로 지금 프레임의 다른 요소를 건드리게 된다.
117	export function frameFromId(id: string, expectUrl?: string): WebFrameMain | null {
118	  const m = /^(\d+):(\d+)$/.exec(id)
119	  if (!m) return null
120	  let f: WebFrameMain | undefined
121	  try { f = webFrameMain.fromId(Number(m[1]), Number(m[2])) } catch { return null }
122	  if (!f) return null
123	  try { if ((f as unknown as { detached?: boolean }).detached === true) return null } catch { /* 구버전엔 없음 */ }
124	  if (expectUrl != null) {
125	    const now = safeUrl(f)
126	    if (now !== expectUrl) return null
127	  }
128	  return f
129	}
130	
131	// ===== 프레임 좌표 오프셋 =====
132	// 실제 입력(sendInputEvent)의 좌표는 **최상위 뷰포트 기준**이다. 프레임 안 요소의 rect 는 그 프레임 기준이므로,
133	// 조상 체인을 따라 <iframe> 요소의 위치를 더해야 진짜 클릭 지점이 나온다.
134	//
135	// 자식 프레임과 부모 문서의 <iframe> 요소를 짝짓는 방법: 부모 JS 에서 `iframe.contentWindow === window.frames[i]`
136	// 로 **참조 동일성**을 비교한다. 이건 교차 출처에서도 허용된다(속성을 읽는 게 아니라 같은 객체인지만 본다).
137	// window.frames 의 순서와 WebFrameMain.frames 의 순서는 둘 다 프레임 트리 자식 순서라 일치한다 —
