93	    <script>
94	      let entries = []
95	      let revealed = new Set()
96	      let query = ''
97	
98	      function escape(s) { return String(s ?? '').replace(/</g, '&lt;') }
99	
100	      async function reload() {
101	        if (!window.internalAPI) {
102	          document.getElementById('list').innerHTML = '<div class="empty">internalAPI 미주입</div>'
103	          return
104	        }
105	        const available = await window.internalAPI.password.available()
106	        const alertEl = document.getElementById('alert')
107	        if (!available) {
108	          alertEl.innerHTML = '<div class="alert">⚠ 현재 시스템에서 safeStorage 가 동작하지 않습니다. 새 비밀번호 저장은 비활성화됩니다. (보통 Linux 에서 libsecret 미설치 시 발생)</div>'
109	        } else {
110	          alertEl.innerHTML = ''
111	        }
112	        entries = await window.internalAPI.password.list()
113	        render()
114	      }
115	
116	      function filtered() {
117	        if (!query.trim()) return entries
118	        const q = query.toLowerCase()
119	        return entries.filter((e) =>
120	          e.origin.toLowerCase().includes(q) || e.username.toLowerCase().includes(q),
121	        )
122	      }
123	
124	      function render() {
125	        const list = document.getElementById('list')
126	        const items = filtered()
127	        if (items.length === 0) {
128	          list.innerHTML = entries.length === 0
129	            ? '<div class="empty">저장된 비밀번호가 없습니다.<br/>웹사이트에서 로그인하면 자동으로 저장됩니다.</div>'
130	            : '<div class="empty">검색 결과 없음</div>'
131	          return
132	        }
133	        list.innerHTML = items.map(function(e) {
134	          const isRevealed = revealed.has(e.id)
135	          const pwCell = isRevealed
136	            ? '<span class="pw" id="pw-' + e.id + '">…</span>'
137	            : '<span class="pw">••••••••</span>'
138	          return '<div class="item">'
139	            + '<div class="origin">' + escape(e.origin) + '</div>'
140	            + '<div class="username">' + escape(e.username) + '</div>'
141	            + pwCell
142	            + '<button class="btn" data-reveal="' + e.id + '">' + (isRevealed ? '숨기기' : '보기') + '</button>'
143	            + '<button class="btn" data-copy="' + e.id + '">복사</button>'
144	            + '<button class="btn danger" data-remove="' + e.id + '">삭제</button>'
145	            + '</div>'
146	        }).join('')
