148	        list.querySelectorAll('[data-reveal]').forEach(function(btn) {
149	          btn.addEventListener('click', async function() {
150	            const id = btn.dataset.reveal
151	            if (revealed.has(id)) {
152	              revealed.delete(id)
153	              render()
154	              return
155	            }
156	            const plain = await window.internalAPI.password.reveal(id)
157	            if (plain === null) {
158	              alert('복호화에 실패했습니다.')
159	              return
160	            }
161	            revealed.add(id)
162	            render()
163	            const el = document.getElementById('pw-' + id)
164	            if (el) el.textContent = plain
165	          })
166	        })
167	        list.querySelectorAll('[data-copy]').forEach(function(btn) {
168	          btn.addEventListener('click', async function() {
169	            const id = btn.dataset.copy
170	            const plain = await window.internalAPI.password.reveal(id)
171	            if (plain === null) { alert('복호화 실패'); return }
172	            try {
173	              await navigator.clipboard.writeText(plain)
174	              const orig = btn.textContent
175	              btn.textContent = '복사됨 ✓'
176	              setTimeout(function() { btn.textContent = orig }, 1200)
177	            } catch (e) {
178	              alert('클립보드 접근 실패')
179	            }
180	          })
181	        })
182	        list.querySelectorAll('[data-remove]').forEach(function(btn) {
183	          btn.addEventListener('click', async function() {
184	            const id = btn.dataset.remove
185	            const e = entries.find(function(x) { return x.id === id })
186	            if (!e) return
187	            if (!confirm('"' + e.origin + '" 의 "' + e.username + '" 비밀번호를 삭제할까요?')) return
188	            await window.internalAPI.password.remove(id)
189	          })
190	        })
191	      }
