200	          entries = list
201	          // revealed 셋의 무효 항목 제거
202	          const ids = new Set(list.map(function(e) { return e.id }))
203	          revealed = new Set(Array.from(revealed).filter(function(id) { return ids.has(id) }))
204	          render()
205	        })
206	      }
