8	  const parts = key.split('.')
9	  let cur: unknown = data
10	  for (const p of parts) {
11	    if (cur && typeof cur === 'object' && p in (cur as Record<string, unknown>)) {
12	      cur = (cur as Record<string, unknown>)[p]
13	    } else {
14	      return fallback ?? key
15	    }
16	  }
