20	export function flatten(): Record<string, string> {
21	  const out: Record<string, string> = {}
22	  function walk(obj: unknown, prefix: string) {
23	    if (obj && typeof obj === 'object') {
24	      for (const [k, v] of Object.entries(obj)) {
25	        const next = prefix ? `${prefix}.${k}` : k
26	        if (v && typeof v === 'object') walk(v, next)
27	        else if (typeof v === 'string') out[next] = v
28	      }
29	    }
30	  }
31	  walk(data, '')
32	  return out
