// 일회용 진단 — 제품 PROBE_SCRIPT 의 오류 문구 정규식을 실제 본문에 대고 본다.
const body = '로그인\n\n비밀번호가 올바르지 않습니다.\n\n아이디  비밀번호  로그인'

// 제품이 런타임에 만드는 문자열과 **같은** 정규식 소스(auto-login.ts 의 템플릿 리터럴이 풀린 결과)
const src = "[^\\n]{0,60}(비밀번호[^\\n]{0,12}(틀렸|올바르지|일치하지|다릅니다)|아이디[^\\n]{0,12}(틀렸|올바르지|일치하지)|로그인[^\\n]{0,8}(실패|할 수 없)|incorrect\\s+(password|username|email)|invalid\\s+(password|credentials|login|username)|didn'?t match|wrong password|authentication failed)[^\\n]{0,60}"
console.log('정규식 소스:', src.slice(0, 50))
const re = new RegExp(src, 'i')
const m = body.match(re)
console.log('매치:', m ? JSON.stringify(m[0]) : 'NO-MATCH')

// 본문 정규화(제품이 하는 replace) 후에도 같은가
const norm = body.replace(/\n{3,}/g, '\n\n').trim()
console.log('정규화 후 매치:', norm.match(re) ? 'OK' : 'NO-MATCH')
console.log('정규화 본문:', JSON.stringify(norm))

